def nearest(rects, i, j):
    best=None
    for name,(r0,r1,c0,c1) in rects.items():
        dr=max(r0-i,0,i-r1); dc=max(c0-j,0,j-c1)
        d=dr+dc
        if best is None or d<best[1]: best=(name,d)
    return best
